#[AsMessageHandler]
public function onPaid(PaymentCharged $e): void
{
    $saga = $this->sagas->find($e->orderId);
    if ('started' !== $saga->step()) {
        return;
    }
    $saga->moveTo('paid');
    $this->em->flush();
    $this->bus->dispatch(new ReserveStock($e->orderId));
}
